import{_ as t,o as r,c as o,ag as a}from"./chunks/framework.qXLDknWC.js";const u=JSON.parse('{"title":"Creator Notes Preview","description":"","frontmatter":{},"headers":[],"relativePath":"features/creator-notes.md","filePath":"features/creator-notes.md"}'),s={name:"features/creator-notes.md"};function i(n,e,l,d,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="creator-notes-preview" tabindex="-1">Creator Notes Preview <a class="header-anchor" href="#creator-notes-preview" aria-label="Permalink to &quot;Creator Notes Preview&quot;">​</a></h1><p>The <strong>Creator Notes</strong> tab lets you write notes for other users who import your character card. Unlike other text fields, Creator Notes supports <strong>HTML and CSS</strong> with a live sandboxed preview.</p><h2 id="writing-creator-notes" tabindex="-1">Writing Creator Notes <a class="header-anchor" href="#writing-creator-notes" aria-label="Permalink to &quot;Writing Creator Notes&quot;">​</a></h2><p>Type your content in the editor on the Creator Notes tab. You can write:</p><ul><li><strong>Plain text</strong> — Displayed as-is with a monospace font in the preview.</li><li><strong>HTML</strong> — Any markup tags (headings, lists, styled text, etc.) are rendered in the preview.</li><li><strong>CSS</strong> — Style rules in <code>&lt;style&gt;</code> blocks are applied within the preview sandbox.</li></ul><h2 id="preview-modal" tabindex="-1">Preview Modal <a class="header-anchor" href="#preview-modal" aria-label="Permalink to &quot;Preview Modal&quot;">​</a></h2><p>Click the <strong>preview button</strong> to open a full-screen preview modal that renders your Creator Notes content exactly as other users would see it. The modal shows:</p><ul><li>A dark-themed sandboxed iframe with your rendered HTML/CSS content.</li><li>An <strong>Add to Editor</strong> button that inserts the content back into the editor.</li><li>A <strong>Close</strong> button (or press <code>Escape</code>).</li></ul><h3 id="sandboxed-rendering" tabindex="-1">Sandboxed Rendering <a class="header-anchor" href="#sandboxed-rendering" aria-label="Permalink to &quot;Sandboxed Rendering&quot;">​</a></h3><p>The preview renders inside an <code>&lt;iframe&gt;</code> with the <code>sandbox=&quot;allow-same-origin&quot;</code> attribute. This means:</p><ul><li>Your HTML and CSS are isolated from the rest of the app — styles won&#39;t leak out.</li><li>Scripts and form submissions are blocked for security.</li><li>The preview environment provides a dark gradient background and a base sans-serif font stack.</li></ul><p>If your content contains no HTML tags, it&#39;s displayed as plain preformatted text with a monospace font.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Test with the preview</strong> — Always check your styled notes in the preview before exporting, to make sure they look the way you intended.</li><li><strong>Keep it self-contained</strong> — Since the preview is sandboxed, external resources (fonts, images, scripts) may not load. Include styles inline or in <code>&lt;style&gt;</code> tags.</li><li><strong>Dark theme only</strong> — The preview environment uses a dark color scheme. Design your CSS accordingly.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook editor</a></li><li><a href="/CharacterVault/docs/features/import-export">Import &amp; export</a></li></ul>',16)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
